/*
 * frick-fsw - PUS reference services
 *
 * Implements the reference PUS-C service set on top of the backend agnostic
 * core. Each handler receives the decoded TC secondary header plus the
 * application data and returns FF_SUCCESS / an error code.
 *
 *  Service 1  Request verification   (generated by the core, see pus.c)
 *  Service 3  Housekeeping           create/delete/enable/disable/report
 *  Service 5  Event reporting        (emitted by EVS, see pus.c)
 *  Service 6  Memory management      memory dump (region checked)
 *  Service 8  Function management    function invocation
 *  Service 9  Time management        set/report time
 *  Service 11 Scheduling             stub (returns NOT_IMPLEMENTED)
 *  Service 17 Test                   connection test / ping
 *  Service 20 On-board parameters    set/report parameter
 *
 * Copyright (C) 2026 Ilfrick
 * https://github.com/ilfrick/frick-fsw | https://www.housefz.com/git/ilfrick/frick-fsw
 * SPDX-License-Identifier: MPL-2.0
 */
#include "pus.h"
#include "core/time/time.h"
#include <stddef.h>
#include <string.h>

#define FF_PUS_MAX_REG 16u
#define FF_PUS_MAX_MEM_REGIONS 8u
#define FF_PUS_MAX_HK_REPORTS 16u

typedef struct
{
    bool used;
    uint8_t id;
    FF_Pus_DataProvider_t fn;
} ff_provider_t;
typedef struct
{
    bool used;
    uint8_t id;
    FF_Pus_ParamSetter_t fn;
} ff_setter_t;
typedef struct
{
    bool used;
    uint8_t id;
    FF_Pus_FunctionHandler_t fn;
} ff_func_t;
typedef struct
{
    bool used;
    uint8_t report_id;
    uint8_t provider_id;
    bool enabled;
} ff_hk_report_t;
typedef struct
{
    uint8_t id;
    const uint8_t *base;
    uint32_t size;
    bool used;
} ff_mem_region_t;

static ff_provider_t g_hk_providers[FF_PUS_MAX_REG];
static ff_provider_t g_param_providers[FF_PUS_MAX_REG];
static ff_setter_t g_param_setters[FF_PUS_MAX_REG];
static ff_func_t g_functions[FF_PUS_MAX_REG];
static ff_hk_report_t g_hk_reports[FF_PUS_MAX_HK_REPORTS];
static ff_mem_region_t g_mem_regions[FF_PUS_MAX_MEM_REGIONS];

/* ---- little big-endian helpers ----------------------------------- */

static uint16_t rd_u16(const uint8_t *p)
{
    return (uint16_t)(((uint16_t)p[0] << 8) | p[1]);
}
static uint32_t rd_u32(const uint8_t *p)
{
    return ((uint32_t)p[0] << 24) | ((uint32_t)p[1] << 16) | ((uint32_t)p[2] << 8) | p[3];
}
static void wr_u16(uint8_t *p, uint16_t v)
{
    p[0] = (uint8_t)(v >> 8);
    p[1] = (uint8_t)v;
}
static void wr_u32(uint8_t *p, uint32_t v)
{
    p[0] = (uint8_t)(v >> 24);
    p[1] = (uint8_t)(v >> 16);
    p[2] = (uint8_t)(v >> 8);
    p[3] = (uint8_t)v;
}

static FF_Pus_DataProvider_t find_provider(ff_provider_t *tbl, uint8_t id)
{
    for (uint16_t i = 0; i < FF_PUS_MAX_REG; i++) {
        if (tbl[i].used && (tbl[i].id == id)) {
            return tbl[i].fn;
        }
    }
    return NULL;
}

/* ---- Registration API -------------------------------------------- */

static FF_Status_t reg_provider(ff_provider_t *tbl, uint8_t id, FF_Pus_DataProvider_t fn)
{
    if (fn == NULL) {
        return FF_INVALID_ARGUMENT;
    }
    /* Reject duplicate provider ids so a later registration cannot silently
     * shadow an earlier provider (NC-EXT-23, C-15). */
    for (uint16_t i = 0; i < FF_PUS_MAX_REG; i++) {
        if (tbl[i].used && (tbl[i].id == id)) {
            return FF_ALREADY_EXISTS;
        }
    }
    for (uint16_t i = 0; i < FF_PUS_MAX_REG; i++) {
        if (!tbl[i].used) {
            tbl[i].used = true;
            tbl[i].id = id;
            tbl[i].fn = fn;
            return FF_SUCCESS;
        }
    }
    return FF_NO_RESOURCE;
}

FF_Status_t FF_PusRegisterHkProvider(uint8_t id, FF_Pus_DataProvider_t provider)
{
    return reg_provider(g_hk_providers, id, provider);
}
FF_Status_t FF_PusRegisterParamProvider(uint8_t id, FF_Pus_DataProvider_t provider)
{
    return reg_provider(g_param_providers, id, provider);
}

FF_Status_t FF_PusRegisterParamSetter(uint8_t id, FF_Pus_ParamSetter_t setter)
{
    if (setter == NULL) {
        return FF_INVALID_ARGUMENT;
    }
    /* Reject duplicate setter ids so a later registration cannot silently shadow
     * an earlier setter (NC-EXT-23, C-16). */
    for (uint16_t i = 0; i < FF_PUS_MAX_REG; i++) {
        if (g_param_setters[i].used && (g_param_setters[i].id == id)) {
            return FF_ALREADY_EXISTS;
        }
    }
    for (uint16_t i = 0; i < FF_PUS_MAX_REG; i++) {
        if (!g_param_setters[i].used) {
            g_param_setters[i].used = true;
            g_param_setters[i].id = id;
            g_param_setters[i].fn = setter;
            return FF_SUCCESS;
        }
    }
    return FF_NO_RESOURCE;
}

FF_Status_t FF_PusRegisterFunction(uint8_t id, FF_Pus_FunctionHandler_t fn)
{
    if (fn == NULL) {
        return FF_INVALID_ARGUMENT;
    }
    /* Reject duplicate function ids so a later registration cannot silently
     * shadow an earlier function (NC-EXT-23, C-16). */
    for (uint16_t i = 0; i < FF_PUS_MAX_REG; i++) {
        if (g_functions[i].used && (g_functions[i].id == id)) {
            return FF_ALREADY_EXISTS;
        }
    }
    for (uint16_t i = 0; i < FF_PUS_MAX_REG; i++) {
        if (!g_functions[i].used) {
            g_functions[i].used = true;
            g_functions[i].id = id;
            g_functions[i].fn = fn;
            return FF_SUCCESS;
        }
    }
    return FF_NO_RESOURCE;
}

FF_Status_t FF_PusRegisterMemoryRegion(uint8_t region_id, const void *base, uint32_t size)
{
    if ((region_id == 0u) || (base == NULL) || (size == 0u)) {
        return FF_INVALID_ARGUMENT;
    }
    for (uint16_t i = 0; i < FF_PUS_MAX_MEM_REGIONS; i++) {
        if (g_mem_regions[i].used && (g_mem_regions[i].id == region_id)) {
            return FF_ALREADY_EXISTS;
        }
    }
    for (uint16_t i = 0; i < FF_PUS_MAX_MEM_REGIONS; i++) {
        if (!g_mem_regions[i].used) {
            g_mem_regions[i].used = true;
            g_mem_regions[i].id = region_id;
            g_mem_regions[i].base = (const uint8_t *)base;
            g_mem_regions[i].size = size;
            return FF_SUCCESS;
        }
    }
    return FF_NO_RESOURCE;
}

/* ---- Service 3 : housekeeping ------------------------------------ */

static FF_Status_t svc3_create(const FF_Pus_TcHdr_t *tc, const uint8_t *d, uint16_t len)
{
    (void)tc;
    if (len < 2u) {
        return FF_BAD_SIZE;
    }
    uint8_t report_id = d[0];
    uint8_t provider = d[1];
    for (uint16_t i = 0; i < FF_PUS_MAX_HK_REPORTS; i++) {
        if (g_hk_reports[i].used && (g_hk_reports[i].report_id == report_id)) {
            return FF_ALREADY_EXISTS;
        }
    }
    for (uint16_t i = 0; i < FF_PUS_MAX_HK_REPORTS; i++) {
        if (!g_hk_reports[i].used) {
            g_hk_reports[i].used = true;
            g_hk_reports[i].report_id = report_id;
            g_hk_reports[i].provider_id = provider;
            g_hk_reports[i].enabled = true;
            return FF_SUCCESS;
        }
    }
    return FF_NO_RESOURCE;
}

static FF_Status_t svc3_delete(const FF_Pus_TcHdr_t *tc, const uint8_t *d, uint16_t len)
{
    (void)tc;
    if (len < 1u) {
        return FF_BAD_SIZE;
    }
    for (uint16_t i = 0; i < FF_PUS_MAX_HK_REPORTS; i++) {
        if (g_hk_reports[i].used && (g_hk_reports[i].report_id == d[0])) {
            g_hk_reports[i].used = false;
            return FF_SUCCESS;
        }
    }
    return FF_NOT_FOUND;
}

static FF_Status_t svc3_enable(const FF_Pus_TcHdr_t *tc, const uint8_t *d, uint16_t len)
{
    (void)tc;
    if (len < 1u) {
        return FF_BAD_SIZE;
    }
    for (uint16_t i = 0; i < FF_PUS_MAX_HK_REPORTS; i++) {
        if (g_hk_reports[i].used && (g_hk_reports[i].report_id == d[0])) {
            g_hk_reports[i].enabled = true;
            return FF_SUCCESS;
        }
    }
    return FF_NOT_FOUND;
}

static FF_Status_t svc3_disable(const FF_Pus_TcHdr_t *tc, const uint8_t *d, uint16_t len)
{
    (void)tc;
    if (len < 1u) {
        return FF_BAD_SIZE;
    }
    for (uint16_t i = 0; i < FF_PUS_MAX_HK_REPORTS; i++) {
        if (g_hk_reports[i].used && (g_hk_reports[i].report_id == d[0])) {
            g_hk_reports[i].enabled = false;
            return FF_SUCCESS;
        }
    }
    return FF_NOT_FOUND;
}

static FF_Status_t svc3_report(const FF_Pus_TcHdr_t *tc, const uint8_t *d, uint16_t len)
{
    (void)tc;
    if ((len < 2u) || (d[0] == 0u) || (len != (uint16_t)(1u + d[0]))) {
        return FF_BAD_SIZE;
    }

    FF_Status_t rc = FF_SUCCESS;
    for (uint16_t requested = 0u; requested < d[0]; requested++) {
        uint8_t report_id = d[requested + 1u];
        ff_hk_report_t *report = NULL;
        for (uint16_t i = 0u; i < FF_PUS_MAX_HK_REPORTS; i++) {
            if (g_hk_reports[i].used && (g_hk_reports[i].report_id == report_id)) {
                report = &g_hk_reports[i];
                break;
            }
        }
        if (report == NULL) {
            if (rc == FF_SUCCESS) {
                rc = FF_NOT_FOUND;
            }
            continue;
        }
        /* TC[3,27] is a one-shot request and is independent of the report's
         * periodic-generation enabled/disabled state. */
        FF_Pus_DataProvider_t prov = find_provider(g_hk_providers, report->provider_id);
        if (prov == NULL) {
            if (rc == FF_SUCCESS) {
                rc = FF_NOT_FOUND;
            }
            continue;
        }
        uint8_t payload[FF_PUS_MAX_TM_FRAME];
        uint16_t cap = (uint16_t)(sizeof(payload) - 1u);
        uint16_t plen = cap;
        payload[0] = report_id;
        FF_Status_t provider_st = prov(report_id, &payload[1], &plen);
        if (provider_st == FF_SUCCESS) {
            /* Validate the provider-reported length before encoding/copying it
             * into the TM frame; a provider that over-reports its own bound must
             * not produce a malformed/oversized telemetry packet (NC-EXT-24,
             * C-16). */
            if (plen > cap) {
                if (rc == FF_SUCCESS) {
                    rc = FF_BAD_SIZE;
                }
                continue;
            }
            FF_Status_t send_st =
                FF_PusSendTm(FF_PUS_SERVICE_HK, 25u, payload, (uint16_t)(plen + 1u));
            if ((send_st != FF_SUCCESS) && (rc == FF_SUCCESS)) {
                rc = send_st;
            }
        }
        else if (rc == FF_SUCCESS) {
            /* Do not acknowledge a requested report as successful when its
             * provider failed to produce the requested data. */
            rc = provider_st;
        }
    }
    return rc;
}

/* ---- Service 6 : memory management (region bounded dump) --------- */

static FF_Status_t svc6_dump(const FF_Pus_TcHdr_t *tc, const uint8_t *d, uint16_t len)
{
    (void)tc;
    if (len != 7u) {
        return FF_BAD_SIZE;
    }
    uint8_t region_id = d[0];
    uint32_t offset = rd_u32(&d[1]);
    uint16_t size = rd_u16(&d[5]);
    if ((region_id == 0u) || (size == 0u) || (size > FF_PUS_MAX_TM_FRAME)) {
        return FF_BAD_SIZE;
    }

    for (uint16_t i = 0; i < FF_PUS_MAX_MEM_REGIONS; i++) {
        if (!g_mem_regions[i].used || (g_mem_regions[i].id != region_id)) {
            continue;
        }
        /* Provisional profile: region ID plus a 32-bit byte offset. The wire
         * value is never a host/target pointer; subtraction-based checks avoid
         * overflow at the region boundary. */
        if ((offset <= g_mem_regions[i].size) &&
            ((uint32_t)size <= (g_mem_regions[i].size - offset))) {
            const uint8_t *src = g_mem_regions[i].base + (ptrdiff_t)offset;
            return FF_PusSendTm(FF_PUS_SERVICE_MEMORY, 6u, src, size);
        }
    }
    return FF_ERROR; /* address outside any registered region */
}

/* ---- Service 8 : function management ----------------------------- */

static FF_Status_t svc8_function(const FF_Pus_TcHdr_t *tc, const uint8_t *d, uint16_t len)
{
    (void)tc;
    if (len < 1u) {
        return FF_BAD_SIZE;
    }
    uint8_t func_id = d[0];
    for (uint16_t i = 0; i < FF_PUS_MAX_REG; i++) {
        if (g_functions[i].used && (g_functions[i].id == func_id)) {
            FF_Status_t rc = g_functions[i].fn(&d[1], (uint16_t)(len - 1u));
            uint8_t resp[2];
            resp[0] = func_id;
            resp[1] = (uint8_t)((rc == FF_SUCCESS) ? 0u : 1u);
            (void)FF_PusSendTm(FF_PUS_SERVICE_FUNCTION, 2u, resp, sizeof(resp));
            return rc;
        }
    }
    return FF_NOT_FOUND;
}

/* ---- Service 9 : time management --------------------------------- */

/* PUS-C on-wire time interchange carries the 6-octet T-field of the CUC with
 * the P-field implicit by interface agreement (see ICD §5). The explicit
 * 7-octet self-describing form (P-field 0x2E + T-field) is produced/consumed
 * only by FF_TimeCucEncode/Decode and must never be accepted here: any other
 * length is rejected so a leading P byte can never be mis-parsed as the MSB
 * of the coarse field (R3 review NC-1). */
static FF_Status_t svc9_set_time(const FF_Pus_TcHdr_t *tc, const uint8_t *d, uint16_t len)
{
    uint32_t coarse;
    uint16_t fine;
    uint64_t ns;

    (void)tc;
    if (len != 6u) {
        return FF_BAD_SIZE;
    }
    coarse = rd_u32(&d[0]);
    fine = rd_u16(&d[4]);
    ns = (uint64_t)coarse * 1000000000ULL + ((uint64_t)fine * 1000000000ULL) / 65536ULL;
    return FF_TimeSetUtcNs(ns);
}

static FF_Status_t svc9_report_time(const FF_Pus_TcHdr_t *tc, const uint8_t *d, uint16_t len)
{
    (void)tc;
    (void)d;
    (void)len;
    uint8_t payload[6];
    uint32_t coarse = 0u;
    uint16_t fine = 0u;
    (void)FF_TimeGetCuc(&coarse, &fine);
    wr_u32(&payload[0], coarse);
    wr_u16(&payload[4], fine);
    return FF_PusSendTm(FF_PUS_SERVICE_TIME, 2u, payload, sizeof(payload));
}

/* ---- Service 11 : scheduling (stub) ------------------------------ */

static FF_Status_t svc11_stub(const FF_Pus_TcHdr_t *tc, const uint8_t *d, uint16_t len)
{
    (void)tc;
    (void)d;
    (void)len;
    /* S11 is registered so unknown-service dispatch (PUS service 1 subservice 9)
     * is never returned for it, but it is a stub: report transparently (NC-EXT-22,
     * C-15). A dedicated event makes the stub status observable to operators and
     * tests rather than a silent NOT_IMPLEMENTED. */
    (void)FF_EvsSend(FF_EVS_PUS_TC_ERR, FF_EVS_WARNING, 0u,
                     "PUS service 11 scheduling not implemented (stub)");
    return FF_NOT_IMPLEMENTED;
}

/* ---- Service 17 : test ------------------------------------------- */

static FF_Status_t svc17_ping(const FF_Pus_TcHdr_t *tc, const uint8_t *d, uint16_t len)
{
    (void)tc;
    return FF_PusSendTm(FF_PUS_SERVICE_TEST, 2u, d, len);
}

/* ---- Service 20 : on-board parameters ---------------------------- */

static FF_Status_t svc20_set(const FF_Pus_TcHdr_t *tc, const uint8_t *d, uint16_t len)
{
    (void)tc;
    if (len < 1u) {
        return FF_BAD_SIZE;
    }
    for (uint16_t i = 0; i < FF_PUS_MAX_REG; i++) {
        if (g_param_setters[i].used && (g_param_setters[i].id == d[0])) {
            return g_param_setters[i].fn(d[0], &d[1], (uint16_t)(len - 1u));
        }
    }
    return FF_NOT_FOUND;
}

static FF_Status_t svc20_report(const FF_Pus_TcHdr_t *tc, const uint8_t *d, uint16_t len)
{
    (void)tc;
    if (len < 1u) {
        return FF_BAD_SIZE;
    }
    FF_Pus_DataProvider_t prov = find_provider(g_param_providers, d[0]);
    if (prov == NULL) {
        return FF_NOT_FOUND;
    }
    uint8_t payload[FF_PUS_MAX_TM_FRAME];
    uint16_t cap = (uint16_t)(sizeof(payload) - 1u);
    uint16_t plen = cap;
    payload[0] = d[0];
    if (prov(d[0], &payload[1], &plen) != FF_SUCCESS) {
        return FF_ERROR;
    }
    /* Validate the provider-reported length before encoding/copying it into the
     * TM frame; a provider that over-reports its own bound must not produce a
     * malformed/oversized telemetry packet (NC-EXT-24, C-16). */
    if (plen > cap) {
        return FF_BAD_SIZE;
    }
    return FF_PusSendTm(FF_PUS_SERVICE_PARAMETER, 4u, payload, (uint16_t)(plen + 1u));
}

/* ---- Registration of the core service set ------------------------ */

FF_Status_t FF_PusRegisterCoreServices(void)
{
    /* Reset the service registries so init is idempotent and tests are
     * order-independent (FRICK-REVIEW-0077 R1-02). */
    memset(g_hk_providers, 0, sizeof(g_hk_providers));
    memset(g_param_providers, 0, sizeof(g_param_providers));
    memset(g_param_setters, 0, sizeof(g_param_setters));
    memset(g_functions, 0, sizeof(g_functions));
    memset(g_hk_reports, 0, sizeof(g_hk_reports));
    memset(g_mem_regions, 0, sizeof(g_mem_regions));

    struct
    {
        uint8_t service;
        uint8_t subservice;
        FF_Pus_Handler_t handler;
    } table[] = {
        {3u, 1u, svc3_create},   {3u, 3u, svc3_delete},   {3u, 5u, svc3_enable},
        {3u, 6u, svc3_disable},  {3u, 27u, svc3_report},  {6u, 5u, svc6_dump},
        {8u, 1u, svc8_function}, {9u, 1u, svc9_set_time}, {9u, 2u, svc9_report_time},
        {11u, 1u, svc11_stub},   {11u, 2u, svc11_stub},   {17u, 1u, svc17_ping},
        {20u, 1u, svc20_set},    {20u, 3u, svc20_report},
    };

    for (size_t i = 0; i < (sizeof(table) / sizeof(table[0])); i++) {
        if (FF_PusRegisterService(table[i].service, table[i].subservice, table[i].handler) !=
            FF_SUCCESS) {
            return FF_ERROR;
        }
    }
    return FF_SUCCESS;
}
